/**
 * Listing store (JSON file) + Haversine search.
 * Data lives in data/listings.json and is generated by `npm run seed`.
 * Everything in it is SAMPLE data (is_sample: true).
 */
import "server-only";
import fs from "node:fs";
import path from "node:path";
import { haversine } from "./geo";
import type { Gender, Listing, ListingHit } from "./types";

let cache: { mtime: number; listings: Listing[] } | null = null;

export function loadListings(): Listing[] {
  const file = path.join(process.cwd(), "data", "listings.json");
  const stat = fs.statSync(file, { throwIfNoEntry: false });
  if (!stat) throw new Error("data/listings.json not found. Run `npm run seed` first.");
  if (cache && cache.mtime === stat.mtimeMs) return cache.listings;
  const json = JSON.parse(fs.readFileSync(file, "utf8"));
  cache = { mtime: stat.mtimeMs, listings: json.listings as Listing[] };
  return cache.listings;
}

export function getListing(id: string): Listing | undefined {
  return loadListings().find((l) => l.id === id);
}

export interface SearchParams {
  lat: number;
  lng: number;
  radius_m: number;
  min_price?: number | null;
  max_price?: number | null;
  gender?: Gender | null;
}

/** Tolerances used to surface "near misses" so the agent can reason about trade-offs. */
export const STRETCH_BUDGET = 0.1; // up to 10% over budget
export const OUTSIDE_RADIUS = 0.35; // up to 35% beyond radius

/**
 * Haversine filter over the local DB.
 * Returns strict matches plus clearly-labelled near misses
 * (slightly over budget or slightly outside the radius, never both).
 */
export function searchListings(p: SearchParams): ListingHit[] {
  const hits: ListingHit[] = [];
  for (const l of loadListings()) {
    if (p.gender && p.gender !== "any" && l.gender !== "any" && l.gender !== p.gender) continue;
    const d = Math.round(haversine(p.lat, p.lng, l.lat, l.lng));
    const inRadius = d <= p.radius_m;
    const nearRadius = d <= p.radius_m * (1 + OUTSIDE_RADIUS);
    const max = p.max_price ?? Infinity;
    const min = p.min_price ?? 0;
    if (l.monthly_rent < min) continue;
    const inBudget = l.monthly_rent <= max;
    const nearBudget = l.monthly_rent <= max * (1 + STRETCH_BUDGET);

    let fit: ListingHit["fit"] | null = null;
    if (inRadius && inBudget) fit = "match";
    else if (inRadius && nearBudget) fit = "stretch";
    else if (nearRadius && inBudget) fit = "outside";
    if (fit) hits.push({ ...l, distance_m: d, fit });
  }
  return hits.sort((a, b) => a.distance_m - b.distance_m);
}

/** Total listings within radius regardless of budget (for "Found 14 PGs, 6 within budget"). */
export function countInRadius(lat: number, lng: number, radius: number): number {
  return loadListings().filter((l) => haversine(lat, lng, l.lat, l.lng) <= radius).length;
}
